insert into services (slug, sort_order, icon, title_en, short_en, description_en, title_te, short_te, description_te, title_hi, short_hi, description_hi, features, image_url, is_active) values
  ('political-survey-research', 1, 'fa-magnifying-glass-chart', 'Political Survey & Research', 'Measure voter sentiment, local issues, leadership perception, and electoral movement through structured political research.', 'We design and run structured political research to measure voter sentiment, surface local issues, gauge leadership perception, and track electoral movement over time. Our surveys are built for the ground realities of Telangana and Andhra Pradesh — sampling that reflects real constituencies, questionnaires in Telugu, and analysis you can act on. Research before rhetoric, always.', 'రాజకీయ సర్వే & పరిశోధన', 'నిర్మాణాత్మక రాజకీయ పరిశోధన ద్వారా ఓటర్ల మనోభావాలు, స్థానిక సమస్యలు మరియు నాయకత్వ అవగాహనను కొలవండి.', '', 'राजनीतिक सर्वेक्षण और अनुसंधान', 'संरचित राजनीतिक अनुसंधान के माध्यम से मतदाता भावना, स्थानीय मुद्दों और नेतृत्व धारणा को मापें।', '', '[{"en":"Research before rhetoric","te":"వాదన కంటే ముందు పరిశోధన","hi":"बयानबाजी से पहले शोध"},{"en":"Constituency-first understanding","te":"నియోజకవర్గం ఆధారిత అవగాహన","hi":"निर्वाचन क्षेत्र-प्रथम समझ"},{"en":"Evidence-led strategy","te":"ఆధారాధారిత వ్యూహం","hi":"साक्ष्य-आधारित रणनीति"}]', NULL, 1),
  ('voter-mapping', 2, 'fa-map-location-dot', 'Voter Mapping', 'Organize constituencies by booth, locality, voter segment, persuasion opportunity, and turnout risk.', 'We map your constituency down to the booth and locality — segmenting voters by community, persuasion opportunity, and turnout risk. This gives your campaign a clear picture of where to invest energy, which segments to prioritize, and where the real battlegrounds lie. Map before movement.', 'ఓటర్ మ్యాపింగ్', 'బూత్, ప్రాంతం, ఓటర్ విభాగం మరియు హాజరు ప్రమాదం ద్వారా నియోజకవర్గాలను నిర్వహించండి.', '', 'मतदाता मानचित्रण', 'बूथ, इलाके, मतदाता वर्ग और मतदान जोखिम के आधार पर निर्वाचन क्षेत्रों को व्यवस्थित करें।', '', '[{"en":"Map before movement","te":"కదలిక కంటే ముందు మ్యాపింగ్","hi":"आंदोलन से पहले मानचित्रण"},{"en":"Segmented voter understanding","te":"విభజిత ఓటర్ అవగాహన","hi":"खंडित मतदाता समझ"},{"en":"Priority outreach zones","te":"ప్రాధాన్యత ప్రచార ప్రాంతాలు","hi":"प्राथमिकता आउटरीच क्षेत्र"}]', NULL, 1),
  ('social-media-campaign', 3, 'fa-hashtag', 'Social Media Political Campaign Management', 'Plan platform strategy, content, rapid response, audience engagement, and performance-led digital communication.', 'We run daily narrative control across every platform — planning platform strategy, producing creative political content, managing rapid response, and driving audience engagement with performance-led digital communication tuned for Telugu audiences.', 'సోషల్ మీడియా రాజకీయ ప్రచార నిర్వహణ', 'ప్లాట్‌ఫారమ్ వ్యూహం, కంటెంట్, వేగవంతమైన స్పందన మరియు ప్రేక్షకుల నిమగ్నతను ప్లాన్ చేయండి.', '', 'सोशल मीडिया राजनीतिक अभियान प्रबंधन', 'प्लेटफ़ॉर्म रणनीति, सामग्री, त्वरित प्रतिक्रिया और दर्शक जुड़ाव की योजना बनाएं।', '', '[{"en":"Daily narrative control","te":"రోజువారీ కథన నియంత్రణ","hi":"दैनिक कथा नियंत्रण"},{"en":"Creative political communication","te":"సృజనాత్మక రాజకీయ సమాచారం","hi":"रचनात्मक राजनीतिक संचार"},{"en":"Platform-ready execution","te":"ప్లాట్‌ఫారమ్-సిద్ధ అమలు","hi":"प्लेटफ़ॉर्म-तैयार निष्पादन"}]', NULL, 1),
  ('booth-management', 4, 'fa-people-group', 'Election Booth Management', 'Booth-first execution with local accountability and review-led field work for maximum turnout.', 'Elections are won booth by booth. We build booth-first execution systems with clear local accountability, structured review cycles, and disciplined field work so no polling booth is left unmanaged on the day that matters most.', 'ఎన్నికల బూత్ నిర్వహణ', 'స్థానిక జవాబుదారీతనం మరియు సమీక్ష ఆధారిత క్షేత్ర పనితో బూత్-ఆధారిత అమలు.', '', 'चुनाव बूथ प्रबंधन', 'स्थानीय जवाबदेही और समीक्षा-आधारित क्षेत्र कार्य के साथ बूथ-प्रथम निष्पादन।', '', '[{"en":"Booth-first execution","te":"బూత్-ఆధారిత అమలు","hi":"बूथ-प्रथम निष्पादन"},{"en":"Local accountability","te":"స్థానిక జవాబుదారీతనం","hi":"स्थानीय जवाबदेही"},{"en":"Review-led field work","te":"సమీక్ష ఆధారిత క్షేత్ర పని","hi":"समीक्षा-आधारित क्षेत्र कार्य"}]', NULL, 1),
  ('rally-yatra-management', 5, 'fa-route', 'Rally & Yatra Management', 'Coordinate routes, crowds, local mobilization, media moments, logistics, and post-event campaign follow-up.', 'From route planning to crowd coordination, local mobilization, media moments, and full logistics — we manage rallies and yatras end to end, and follow up after every event to convert momentum into lasting campaign gains. Movement with message.', 'ర్యాలీ & యాత్ర నిర్వహణ', 'మార్గాలు, జనసమూహాలు, స్థానిక సమీకరణ, మీడియా క్షణాలు మరియు లాజిస్టిక్స్‌ను సమన్వయం చేయండి.', '', 'रैली और यात्रा प्रबंधन', 'मार्ग, भीड़, स्थानीय लामबंदी, मीडिया क्षण और लॉजिस्टिक्स का समन्वय करें।', '', '[{"en":"Movement with message","te":"సందేశంతో కూడిన కదలిక","hi":"संदेश के साथ आंदोलन"},{"en":"Route-led visibility","te":"మార్గ ఆధారిత దృశ్యమానత","hi":"मार्ग-आधारित दृश्यता"},{"en":"Crowd & media coordination","te":"జనసమూహం & మీడియా సమన్వయం","hi":"भीड़ और मीडिया समन्वय"}]', NULL, 1),
  ('event-management', 6, 'fa-calendar-check', 'Event Management', 'Deliver political meetings, public programs, stakeholder events, and campaign activations with disciplined coordination.', 'We deliver political meetings, public programs, stakeholder gatherings, and campaign activations with disciplined coordination — every detail planned, every message aligned, every event built to advance the campaign.', 'ఈవెంట్ నిర్వహణ', 'రాజకీయ సమావేశాలు, ప్రజా కార్యక్రమాలు మరియు ప్రచార కార్యక్రమాలను క్రమశిక్షణతో అందించండి.', '', 'कार्यक्रम प्रबंधन', 'राजनीतिक बैठकें, सार्वजनिक कार्यक्रम और अभियान सक्रियण को अनुशासित समन्वय के साथ प्रदान करें।', '', '[{"en":"Organized public engagement","te":"వ్యవస్థీకృత ప్రజా నిమగ్నత","hi":"संगठित सार्वजनिक जुड़ाव"},{"en":"Campaign-ready event design","te":"ప్రచార-సిద్ధ ఈవెంట్ డిజైన్","hi":"अभियान-तैयार कार्यक्रम डिज़ाइन"},{"en":"Message-led execution","te":"సందేశ ఆధారిత అమలు","hi":"संदेश-आधारित निष्पादन"}]', NULL, 1),
  ('ivr-bulk-calls', 7, 'fa-phone-volume', 'IVR Bulk Calls', 'Reach large voter groups with recorded voice messages, language targeting, scheduling, and response tracking.', 'Reach lakhs of voters with recorded voice messages in Telugu, Hindi, or English. We handle language targeting, scheduling, and response tracking so your campaign message lands at scale with measurable feedback.', 'IVR బల్క్ కాల్స్', 'రికార్డ్ చేసిన వాయిస్ సందేశాలతో పెద్ద ఓటర్ సమూహాలను చేరుకోండి.', '', 'IVR बल्क कॉल', 'रिकॉर्ड किए गए वॉयस संदेशों के साथ बड़े मतदाता समूहों तक पहुंचें।', '', '[{"en":"Recorded voter outreach","te":"రికార్డ్ చేసిన ఓటర్ ప్రచారం","hi":"रिकॉर्ड किया गया मतदाता आउटरीच"},{"en":"Rapid constituency coverage","te":"వేగవంతమైన నియోజకవర్గ కవరేజ్","hi":"तीव्र निर्वाचन क्षेत्र कवरेज"},{"en":"Campaign-ready call flows","te":"ప్రచార-సిద్ధ కాల్ ప్రవాహాలు","hi":"अभियान-तैयार कॉल फ्लो"}]', NULL, 1),
  ('whatsapp-bulk-messaging', 8, 'fa-whatsapp', 'WhatsApp Bulk Messaging', 'Distribute campaign updates, local messages, invitations, and media assets through organized WhatsApp outreach.', 'Distribute campaign updates, localized messages, event invitations, and rich media through organized WhatsApp outreach — the platform where Telugu voters actually spend their time. Direct, personal, and trackable.', 'వాట్సాప్ బల్క్ మెసేజింగ్', 'వ్యవస్థీకృత వాట్సాప్ ద్వారా ప్రచార నవీకరణలు మరియు మీడియాను పంపిణీ చేయండి.', '', 'व्हाट्सएप बल्क मैसेजिंग', 'संगठित व्हाट्सएप के माध्यम से अभियान अपडेट और मीडिया वितरित करें।', '', '[{"en":"Direct campaign updates","te":"ప్రత్యక్ష ప్రచార నవీకరణలు","hi":"प्रत्यक्ष अभियान अपडेट"},{"en":"Localized message distribution","te":"స్థానికీకృత సందేశ పంపిణీ","hi":"स्थानीयकृत संदेश वितरण"},{"en":"Volunteer network support","te":"వాలంటీర్ నెట్‌వర్క్ మద్దతు","hi":"स्वयंसेवक नेटवर्क समर्थन"}]', NULL, 1),
  ('ai-video-messaging', 9, 'fa-clapperboard', 'AI Personalised Video Messaging', 'Create personalized leader videos at scale for constituencies, communities, supporters, and campaign milestones.', 'Create personalized leader videos at scale — addressing constituencies, communities, and supporters by name and locality. AI-driven video outreach that feels one-to-one, delivered at campaign scale.', 'AI వ్యక్తిగతీకృత వీడియో మెసేజింగ్', 'నియోజకవర్గాలు మరియు మద్దతుదారుల కోసం వ్యక్తిగతీకృత నాయకుడి వీడియోలను సృష్టించండి.', '', 'AI व्यक्तिगत वीडियो संदेश', 'निर्वाचन क्षेत्रों और समर्थकों के लिए व्यक्तिगत नेता वीडियो बनाएं।', '', '[{"en":"Personalized voter communication","te":"వ్యక్తిగతీకృత ఓటర్ సమాచారం","hi":"व्यक्तिगत मतदाता संचार"},{"en":"Scalable video outreach","te":"స్కేలబుల్ వీడియో ప్రచారం","hi":"स्केलेबल वीडियो आउटरीच"},{"en":"Leader-led messaging","te":"నాయకుడి ఆధారిత సందేశం","hi":"नेता-आधारित संदेश"}]', NULL, 1),
  ('opinion-exit-poll', 10, 'fa-square-poll-vertical', 'Opinion and Exit Poll', 'Track electoral preference, issue salience, candidate strength, and voting patterns through rigorous polling.', 'Track electoral preference, issue salience, candidate strength, and emerging voting patterns through methodologically rigorous opinion and exit polls — designed and analyzed specifically for the Telugu electorate.', 'అభిప్రాయ & ఎగ్జిట్ పోల్', 'కఠినమైన పోలింగ్ ద్వారా ఎన్నికల ప్రాధాన్యత మరియు ఓటింగ్ నమూనాలను ట్రాక్ చేయండి.', '', 'राय और एग्जिट पोल', 'कठोर मतदान के माध्यम से चुनावी प्राथमिकता और मतदान पैटर्न को ट्रैक करें।', '', '[{"en":"Rigorous methodology","te":"కఠినమైన పద్దతి","hi":"कठोर पद्धति"},{"en":"Candidate strength tracking","te":"అభ్యర్థి బలం ట్రాకింగ్","hi":"उम्मीदवार ताकत ट्रैकिंग"},{"en":"Voting pattern analysis","te":"ఓటింగ్ నమూనా విశ్లేషణ","hi":"मतदान पैटर्न विश्लेषण"}]', NULL, 1),
  ('political-advertising', 11, 'fa-bullhorn', 'Political Advertising', 'Develop message-led creative and media campaigns for public visibility, persuasion, and voter recall.', 'We develop message-led creative and place it across the right media mix — building public visibility, driving persuasion, and maximizing voter recall through advertising built for the Telugu media landscape.', 'రాజకీయ ప్రకటనలు', 'ప్రజా దృశ్యమానత మరియు ఒప్పింపు కోసం సందేశ ఆధారిత సృజనాత్మక ప్రచారాలను అభివృద్ధి చేయండి.', '', 'राजनीतिक विज्ञापन', 'सार्वजनिक दृश्यता और अनुनय के लिए संदेश-आधारित रचनात्मक अभियान विकसित करें।', '', '[{"en":"Message-led creative","te":"సందేశ ఆధారిత సృజనాత్మకత","hi":"संदेश-आधारित रचनात्मकता"},{"en":"Right media mix","te":"సరైన మీడియా మిశ్రమం","hi":"सही मीडिया मिश्रण"},{"en":"Maximized voter recall","te":"గరిష్ట ఓటర్ రీకాల్","hi":"अधिकतम मतदाता स्मरण"}]', NULL, 1),
  ('political-canvassing', 12, 'fa-clipboard-list', 'Political Canvassing', 'Run structured voter-contact programs that capture feedback, identify support, and strengthen local presence.', 'Run structured voter-contact programs that capture real feedback, identify committed support, and steadily strengthen your local presence — turning conversations into campaign intelligence.', 'రాజకీయ కాన్వాసింగ్', 'అభిప్రాయాన్ని సేకరించే మరియు మద్దతును గుర్తించే నిర్మాణాత్మక ఓటర్-సంపర్క కార్యక్రమాలను నిర్వహించండి.', '', 'राजनीतिक कैनवासिंग', 'संरचित मतदाता-संपर्क कार्यक्रम चलाएं जो प्रतिक्रिया एकत्र करें और समर्थन की पहचान करें।', '', '[{"en":"Structured voter contact","te":"నిర్మాణాత్మక ఓటర్ సంపర్కం","hi":"संरचित मतदाता संपर्क"},{"en":"Feedback capture","te":"అభిప్రాయ సేకరణ","hi":"प्रतिक्रिया संग्रह"},{"en":"Support identification","te":"మద్దతు గుర్తింపు","hi":"समर्थन पहचान"}]', NULL, 1),
  ('door-to-door-campaign', 13, 'fa-house-user', 'Door-to-Door Campaign', 'Plan household outreach, volunteer deployment, voter conversations, data capture, and follow-up action.', 'The most personal form of politics. We plan household outreach, deploy and train volunteers, structure voter conversations, capture data at the doorstep, and drive disciplined follow-up action — building trust one home at a time.', 'ఇంటింటి ప్రచారం', 'గృహ ప్రచారం, వాలంటీర్ల నియామకం, ఓటర్ సంభాషణలు మరియు డేటా సేకరణను ప్లాన్ చేయండి.', '', 'घर-घर अभियान', 'घरेलू आउटरीच, स्वयंसेवक तैनाती, मतदाता बातचीत और डेटा संग्रह की योजना बनाएं।', '', '[{"en":"Household outreach planning","te":"గృహ ప్రచార ప్రణాళిక","hi":"घरेलू आउटरीच योजना"},{"en":"Volunteer deployment","te":"వాలంటీర్ నియామకం","hi":"स्वयंसेवक तैनाती"},{"en":"Doorstep data capture","te":"గుమ్మం వద్ద డేటా సేకరణ","hi":"द्वार पर डेटा संग्रह"}]', NULL, 1)
on conflict (slug) do nothing;

